-- ════════════════════════════════════════════════════════════════════
-- migration 043 — ministry_archetypes (Model 3) + ministries.archetype_key
-- Multi-tenant ministry recommender, Layer 1 (archetype library) + the link.
-- FLAT · idempotent · rerun-until-true · RLS STRUCTURE-FIRST (left DISABLED; Phase B enables)
-- Rosehill id inlined: 724f4826-0f83-4ce8-bfc0-83698b79ce6f
-- ════════════════════════════════════════════════════════════════════

-- ── 1. Table (Model 3: church_id NULL = MULTIPLY base, non-NULL = church overlay) ──
CREATE TABLE IF NOT EXISTS ministry_archetypes (
  id            uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  church_id     uuid REFERENCES churches(id) ON DELETE CASCADE,
  archetype_key text NOT NULL,
  name          text,
  summary       text,
  scoring       jsonb NOT NULL DEFAULT '{}'::jsonb,   -- { adv:[], risk:[], profile:{} }
  display_order integer DEFAULT 0,
  active        boolean NOT NULL DEFAULT true,
  created_at    timestamptz NOT NULL DEFAULT now(),
  updated_at    timestamptz NOT NULL DEFAULT now()
);

-- ── 2. Two PARTIAL uniques (Postgres treats NULLs as distinct → #218 trap) ──
CREATE UNIQUE INDEX IF NOT EXISTS uq_archetype_base
  ON ministry_archetypes (archetype_key)            WHERE church_id IS NULL;
CREATE UNIQUE INDEX IF NOT EXISTS uq_archetype_overlay
  ON ministry_archetypes (church_id, archetype_key) WHERE church_id IS NOT NULL;

-- ── 3. Tenant policies (base-or-mine read; mine-only write). RLS left OFF (Phase B). ──
DROP POLICY IF EXISTS archetype_tenant_select ON ministry_archetypes;
CREATE POLICY archetype_tenant_select ON ministry_archetypes FOR SELECT TO authenticated
  USING (church_id IS NULL OR church_id = auth_church_id());
DROP POLICY IF EXISTS archetype_tenant_insert ON ministry_archetypes;
CREATE POLICY archetype_tenant_insert ON ministry_archetypes FOR INSERT TO authenticated
  WITH CHECK (church_id = auth_church_id());
DROP POLICY IF EXISTS archetype_tenant_update ON ministry_archetypes;
CREATE POLICY archetype_tenant_update ON ministry_archetypes FOR UPDATE TO authenticated
  USING (church_id = auth_church_id()) WITH CHECK (church_id = auth_church_id());
DROP POLICY IF EXISTS archetype_tenant_delete ON ministry_archetypes;
CREATE POLICY archetype_tenant_delete ON ministry_archetypes FOR DELETE TO authenticated
  USING (church_id = auth_church_id());
ALTER TABLE ministry_archetypes DISABLE ROW LEVEL SECURITY;   -- NO autostamp trigger: base/overlay church_id is explicit

-- ── 4. The link column on the per-church ministries directory ──
ALTER TABLE ministries ADD COLUMN IF NOT EXISTS archetype_key text;

-- ── 5. Seed 16 BASE archetypes (church_id NULL) ──
