  (NULL, 'children', 'Children''s Ministry', 'Teaching and shepherding kids ages 4-12.', '{"adv": [{"src": "GIFT", "sig": "Teaching strong (≥18)", "w": 3, "key": "gift_teaching_strong", "reason": "Core function — instructing children in Scripture."}, {"src": "GIFT", "sig": "Shepherding strong (≥18)", "w": 3, "key": "gift_shepherding_strong", "reason": "Pastoral care of young hearts."}, {"src": "GIFT", "sig": "Mercy strong (≥18)", "w": 3, "key": "gift_mercy_strong", "reason": "Children need compassionate adults."}, {"src": "GIFT", "sig": "Encouragement strong (≥18)", "w": 2, "key": "gift_exhortation_strong", "reason": "Building up children in their faith identity."}, {"src": "GIFT", "sig": "Hospitality strong (≥18)", "w": 2, "key": "gift_hospitality_strong", "reason": "Welcoming visiting kids and parents."}, {"src": "GIFT", "sig": "Service/Helps strong (≥18)", "w": 2, "key": "gift_service_strong", "reason": "Supports lead teachers."}, {"src": "DISC", "sig": "S primary or secondary", "w": 2, "key": "disc_S", "reason": "Patient, steady — children need consistency."}, {"src": "ENN", "sig": "Type 2 (Helper)", "w": 2, "key": "enn_2", "reason": "Naturally caring; reads kids'' emotions well."}, {"src": "ENN", "sig": "Type 6 (Loyalist)", "w": 2, "key": "enn_6", "reason": "Faithful, dependable — shows up week after week."}, {"src": "STR", "sig": "Developer", "w": 2, "key": "str_Developer", "reason": "Sees potential in each child."}, {"src": "STR", "sig": "Empathy", "w": 2, "key": "str_Empathy", "reason": "Catches the child hurting silently."}, {"src": "STR", "sig": "Includer", "w": 2, "key": "str_Includer", "reason": "Notices the shy or new child."}, {"src": "LL", "sig": "Quality Time primary", "w": 1, "key": "ll_quality_time", "reason": "Gives full presence to kids."}, {"src": "LL", "sig": "Physical Touch primary", "w": 1, "key": "ll_physical_touch", "reason": "Appropriate warmth communicates safety."}], "risk": [{"src": "GIFT", "sig": "Mercy weak (≤8)", "w": 3, "key": "gift_mercy_weak", "reason": "Low compassion is a serious mismatch."}, {"src": "GIFT", "sig": "Teaching weak (≤8)", "w": 2, "key": "gift_teaching_weak", "reason": "Teaching is core — low gift makes it a struggle."}, {"src": "DISC", "sig": "D primary (high)", "w": 3, "key": "disc_D_high", "reason": "Impatience can frighten children."}, {"src": "ENN", "sig": "Type 8 (Challenger)", "w": 3, "key": "enn_8", "reason": "Intensity can overwhelm sensitive children."}, {"src": "STR", "sig": "Command", "w": 2, "key": "str_Command", "reason": "Direct/forceful style not ideal."}, {"src": "STR", "sig": "Competition", "w": 2, "key": "str_Competition", "reason": "Children''s ministry is not performance-driven."}, {"src": "ENN", "sig": "Type 5 (Investigator)", "w": 1, "key": "enn_5", "reason": "May prefer solitary thought."}], "profile": {"primary": ["teaching", "shepherding", "mercy"], "secondary": ["exhortation", "hospitality", "service"]}}'::jsonb, 1, true),
  (NULL, 'campus', 'Campus Ministry', 'Values formation in high schools and colleges.', '{"adv": [{"src": "GIFT", "sig": "Evangelism strong (≥18)", "w": 3, "key": "gift_evangelism_strong", "reason": "Public school context = unchurched students."}, {"src": "GIFT", "sig": "Teaching strong (≥18)", "w": 3, "key": "gift_teaching_strong", "reason": "Primary function."}, {"src": "GIFT", "sig": "Apostleship strong (≥18)", "w": 3, "key": "gift_apostleship_strong", "reason": "Pioneering ministry."}, {"src": "GIFT", "sig": "Wisdom strong (≥18)", "w": 2, "key": "gift_wisdom_strong", "reason": "Students bring complex life issues."}, {"src": "GIFT", "sig": "Encouragement strong (≥18)", "w": 2, "key": "gift_exhortation_strong", "reason": "Encouraging young people."}, {"src": "GIFT", "sig": "Mercy strong (≥18)", "w": 2, "key": "gift_mercy_strong", "reason": "Students carry hidden burdens."}, {"src": "DISC", "sig": "I primary or secondary", "w": 2, "key": "disc_I", "reason": "Engages students through enthusiasm."}, {"src": "ENN", "sig": "Type 1 (Reformer)", "w": 2, "key": "enn_1", "reason": "Values formation is about right and wrong."}, {"src": "ENN", "sig": "Type 7 (Enthusiast)", "w": 1, "key": "enn_7", "reason": "Energy keeps young audiences engaged."}, {"src": "STR", "sig": "Communication", "w": 2, "key": "str_Communication", "reason": "Public speaking is essential."}, {"src": "STR", "sig": "Developer", "w": 2, "key": "str_Developer", "reason": "Sees potential in young people."}, {"src": "STR", "sig": "Learner", "w": 1, "key": "str_Learner", "reason": "Models lifelong learning."}], "risk": [{"src": "GIFT", "sig": "Teaching weak (≤8)", "w": 3, "key": "gift_teaching_weak", "reason": "Teaching is the core function."}, {"src": "DISC", "sig": "C primary (very high)", "w": 2, "key": "disc_C_high", "reason": "Too rigid or academic for teens."}, {"src": "ENN", "sig": "Type 5 (Investigator)", "w": 2, "key": "enn_5", "reason": "Detached style does not connect."}], "profile": {"primary": ["